package io.github.rebrowser.bridge;
import static org.junit.Assert.*;
import java.util.*;
import java.security.MessageDigest;
import org.junit.Test;
public class StreamOwnershipTest {
 static class F extends DocumentRouteTest.F {
  final BridgeBudget.Streams streams=new BridgeBudget.Streams();final BridgeStreamReceiver receiver;
  F(long declared,long max){ready();receiver=new BridgeStreamReceiver(lease,receive("STREAM_BEGIN","\"requestId\":\""+DocumentRouteTest.R+"\",\"streamId\":\""+DocumentRouteTest.S+"\",\"purpose\":\"observation-json\",\"declaredBytes\":"+declared),DocumentRouteTest.R,"observation-json",max,streams);}
  DocumentLease.Received chunk(long seq,byte[] b){return receive("STREAM_CHUNK","\"streamId\":\""+DocumentRouteTest.S+"\",\"sequence\":"+seq+",\"rawBytes\":"+b.length+",\"base64\":\""+Base64.getEncoder().encodeToString(b)+"\"");}
  DocumentLease.Received end(long count,String sha){return receive("STREAM_END","\"streamId\":\""+DocumentRouteTest.S+"\",\"totalBytes\":"+count+",\"sha256\":\""+sha+"\"");}
  String sha(byte[] b)throws Exception{return DocumentLease.hex(MessageDigest.getInstance("SHA-256").digest(b));}
 }
 @Test public void exactChunksLengthShaAndByteOwnership()throws Exception{F f=new F(4,4);f.receiver.creditBeforePost(4);byte[] b={1,2,3,4};f.receiver.acceptChunk(f.chunk(0,b));BridgeStreamReceiver.OwnedChunk c=f.receiver.pollOwned();assertEquals(4,f.streams.ownedBytes());assertTrue(c.borrowedReadOnly().isReadOnly());assertEquals(4,f.receiver.observeEnd(f.end(4,f.sha(b))).receivedBytes());assertTrue(f.streams.hasOwnedStream());f.receiver.close();f.receiver.nativeOwnerEnded();assertTrue(f.streams.hasOwnedStream());c.close();assertFalse(f.streams.hasOwnedStream());assertEquals(0,f.streams.ownedBytes());}
 @Test public void sourceOrPortRetirementCannotResetCreditOrReleaseWork()throws Exception{F f=new F(1,1);f.receiver.creditBeforePost(1);f.receiver.acceptChunk(f.chunk(0,new byte[]{1}));BridgeStreamReceiver.OwnedChunk chunk=f.receiver.pollOwned();f.lease.retire();assertThrows(SecurityException.class,()->f.receiver.pollOwned());f.receiver.close();chunk.close();assertTrue(f.streams.hasOwnedStream());assertNull(f.streams.tryOpen());f.receiver.nativeOwnerEnded();assertFalse(f.streams.hasOwnedStream());}
 @Test public void ownerEndWithoutProducerRetirementDoesNotRecycleSlot(){F f=new F(0,0);f.receiver.nativeOwnerEnded();assertTrue(f.streams.hasOwnedStream());f.receiver.close();assertFalse(f.streams.hasOwnedStream());}
 @Test public void closeCannotReleaseAnExternallyPolledChunk(){F f=new F(2,2);f.receiver.creditBeforePost(2);f.receiver.acceptChunk(f.chunk(0,new byte[]{1,2}));BridgeStreamReceiver.OwnedChunk c=f.receiver.pollOwned();f.receiver.close();f.receiver.nativeOwnerEnded();assertEquals(2,f.streams.ownedBytes());assertTrue(f.streams.hasOwnedStream());c.close();c.close();assertEquals(0,f.streams.ownedBytes());assertFalse(f.streams.hasOwnedStream());}
 @Test public void noCreditRejectsBeforeNativeChunkOwnership(){F f=new F(1,1);assertThrows(IllegalArgumentException.class,()->f.receiver.acceptChunk(f.chunk(0,new byte[]{1})));assertEquals(0,f.streams.ownedBytes());assertEquals(BridgeStreamReceiver.State.FAILED,f.receiver.state());assertTrue(f.streams.hasOwnedStream());}
 @Test public void sequenceGapsAndDuplicateChunksNeverReplay(){F f=new F(2,2);f.receiver.creditBeforePost(2);assertThrows(IllegalArgumentException.class,()->f.receiver.acceptChunk(f.chunk(1,new byte[]{1})));F g=new F(2,2);g.receiver.creditBeforePost(2);g.receiver.acceptChunk(g.chunk(0,new byte[]{1}));assertThrows(IllegalArgumentException.class,()->g.receiver.acceptChunk(g.chunk(0,new byte[]{1})));assertEquals(1,g.streams.ownedBytes());g.receiver.close();assertEquals(0,g.streams.ownedBytes());assertTrue(g.streams.hasOwnedStream());}
 @Test public void creditCannotExceedDeclaredRemainderOrRetainedWindow(){F f=new F(1,1);assertThrows(IllegalArgumentException.class,()->f.receiver.creditBeforePost(2));F g=new F(100_000,100_000);g.receiver.creditBeforePost(65536);assertThrows(IllegalArgumentException.class,()->g.receiver.creditBeforePost(1));byte[] b=new byte[32768];g.receiver.acceptChunk(g.chunk(0,b));g.receiver.acceptChunk(g.chunk(1,b));assertEquals(65536,g.streams.ownedBytes());assertThrows(IllegalArgumentException.class,()->g.receiver.creditBeforePost(1));}
 @Test public void consumerDisposalAllowsAdditionalExplicitCreditNotAutomatic(){F f=new F(65537,65537);f.receiver.creditBeforePost(65536);byte[] b=new byte[32768];f.receiver.acceptChunk(f.chunk(0,b));BridgeStreamReceiver.OwnedChunk c=f.receiver.pollOwned();c.close();assertNotNull(f.receiver.creditBeforePost(1));assertThrows(IllegalArgumentException.class,()->f.receiver.creditBeforePost(32768));}
 @Test public void duplicateStreamAndUnknownDeclarationNeverAllocateDeclaredBody(){F f=new F(64L*1024*1024,64L*1024*1024);assertEquals(0,f.streams.ownedBytes());assertThrows(IllegalStateException.class,()->new BridgeStreamReceiver(f.lease,f.receive("STREAM_BEGIN","\"requestId\":\""+DocumentRouteTest.R+"\",\"streamId\":\""+DocumentRouteTest.S+"\",\"purpose\":\"observation-json\",\"declaredBytes\":0"),DocumentRouteTest.R,"observation-json",1,f.streams));assertThrows(IllegalArgumentException.class,()->new F(100,99));}
 @Test public void endRequiresExactCountAndDigest()throws Exception{F f=new F(1,1);f.receiver.creditBeforePost(1);f.receiver.acceptChunk(f.chunk(0,new byte[]{1}));assertThrows(IllegalArgumentException.class,()->f.receiver.observeEnd(f.end(1,f.sha(new byte[]{2}))));assertEquals(BridgeStreamReceiver.State.FAILED,f.receiver.state());F g=new F(2,2);g.receiver.creditBeforePost(1);g.receiver.acceptChunk(g.chunk(0,new byte[]{1}));assertThrows(IllegalArgumentException.class,()->g.receiver.observeEnd(g.end(1,g.sha(new byte[]{1}))));}
 @Test public void emptyStreamStillRequiresRealOwnerEndAndExactSha()throws Exception{F f=new F(0,0);f.receiver.observeEnd(f.end(0,f.sha(new byte[0])));assertTrue(f.streams.hasOwnedStream());assertEquals(BridgeStreamReceiver.State.END_OBSERVED,f.receiver.state());f.receiver.nativeOwnerEnded();assertFalse(f.streams.hasOwnedStream());}
 @Test public void payloadCloseIsAllowedFromActualConsumerWorker()throws Exception{F f=new F(1,1);f.receiver.creditBeforePost(1);f.receiver.acceptChunk(f.chunk(0,new byte[]{1}));BridgeStreamReceiver.OwnedChunk c=f.receiver.pollOwned();java.nio.ByteBuffer borrowed=c.borrowedReadOnly();Thread worker=new Thread(c::close);worker.start();worker.join();assertEquals(0,borrowed.get(0));assertThrows(IllegalStateException.class,c::borrowedReadOnly);assertEquals(0,f.streams.ownedBytes());assertTrue(f.streams.hasOwnedStream());}
 @Test public void oldChunkCloseCannotReleaseANewSlot(){F f=new F(1,1);f.receiver.creditBeforePost(1);f.receiver.acceptChunk(f.chunk(0,new byte[]{1}));BridgeStreamReceiver.OwnedChunk c=f.receiver.pollOwned();f.receiver.close();f.receiver.nativeOwnerEnded();c.close();BridgeBudget.StreamSlot next=f.streams.tryOpen();assertNotNull(next);c.close();assertTrue(f.streams.hasOwnedStream());next.producerRetired();next.nativeOwnerEnded();assertFalse(f.streams.hasOwnedStream());}
}
